async function openProcessingJob(job) {
  if (!job?.feedUrl || !job?.episodeId) return notify("This record does not contain a resolvable publisher episode.");
  try { await openEpisode(job.feedUrl, job.episodeId); } catch (error) { notify(error.message); }
}
async function cancelProcessingJob(job, button) {
  if (!job?.feedUrl || !job?.episodeId) return;
  if (!window.confirm("Cancel this queued job before a worker starts? This does not cancel active provider work.")) return;
  button.disabled = true;
  try {
    await api("/api/admin/intelligence/cancel", { method: "POST", body: JSON.stringify({ feedUrl: job.feedUrl, episodeId: job.episodeId, reason: "Cancelled from the operations queue." }) });
    notify("Queued job cancelled and audited."); await load("processing"); render();
  } catch (error) { button.disabled = false; notify(error.message); }
}
function bindAttentionActions() {
  document.querySelectorAll("[data-attention]").forEach((button) => button.onclick = async () => {
    const item = state.attentionActions?.[Number(button.dataset.attention)];
    if (!item) return;
    if (item.feedUrl && item.episodeId) return openEpisode(item.feedUrl, item.episodeId).catch((error) => notify(error.message));
    state.view = item.destination || "operations";
    try { await load(); render(); } catch (error) { notify(error.message); }
  });
}
