  document.querySelector("#report-form").onsubmit = async (event) => { event.preventDefault(); const input = Object.fromEntries(new FormData(event.currentTarget)); try { await api(`/api/admin/reports/${encodeURIComponent(report.id)}`, { method: "PATCH", body: JSON.stringify(input) }); notify("Listener report updated and audited."); await load("listeners"); render(); } catch (error) { notify(error.message); } };
