function openCommandPalette() {
  document.querySelector(".command-dialog")?.remove();
  const dialog = document.createElement("section");
  dialog.className = "command-dialog";
  dialog.setAttribute("role", "dialog");
  dialog.setAttribute("aria-modal", "true");
  dialog.setAttribute("aria-label", "Search operations records");
  dialog.innerHTML = `<div class="command-card"><div class="panel-head"><div><span class="eyebrow">Global search</span><h3>Find a record</h3></div><button class="secondary" type="button" data-command-close>Close</button></div><form id="command-search"><label>Search podcasts, episodes, support reports and permitted listener records<input name="q" autocomplete="off" placeholder="Start typing…" required autofocus></label><button class="primary">Search records</button></form><div class="command-results" aria-live="polite"><p class="muted">Use a podcast, episode, processing or rights term. Results respect your administrator role.</p></div></div>`;
  document.body.append(dialog);
  const close = () => dialog.remove();
  dialog.querySelector("[data-command-close]").onclick = close;
  dialog.addEventListener("click", (event) => { if (event.target === dialog) close(); });
  dialog.querySelector("#command-search").onsubmit = async (event) => {
    event.preventDefault(); const form = new FormData(event.currentTarget), results = dialog.querySelector(".command-results"); results.innerHTML = `<p class="muted">Searching authoritative records…</p>`;
    try {
      const payload = await api(`/api/admin/search?${new URLSearchParams({ q: form.get("q") })}`);
      const groups = payload.groups || [];
      results.innerHTML = groups.length ? groups.map((group) => `<section><h4>${html(label(group.type))}</h4>${group.items.map((item, index) => `<button class="command-result" data-command-group="${html(group.type)}" data-command-item="${index}"><strong>${html(item.title)}</strong><span>${html(item.subtitle)}</span></button>`).join("")}</section>`).join("") : `<p class="muted">No permitted operations record matches that search.</p>`;
      state.commandResults = groups;
      results.querySelectorAll("[data-command-group]").forEach((button) => button.onclick = async () => {
        const group = state.commandResults.find((candidate) => candidate.type === button.dataset.commandGroup);
        const item = group?.items[Number(button.dataset.commandItem)]; if (!item) return;
        close();
        try {
          if (item.type === "PODCAST") return openPodcast(item.feedUrl);
          if (item.type === "EPISODE" || item.type === "RIGHTS") return item.episodeId ? openEpisode(item.feedUrl, item.episodeId) : (state.view = "rights", await load(), render());
          state.view = item.type === "REPORT" || item.type === "LISTENER" ? "listeners" : "operations"; await load(); render();
        } catch (error) { notify(error.message); }
      });
    } catch (error) { results.innerHTML = `<p class="error">${html(error.message)}</p>`; }
  };
  dialog.querySelector("input").focus();
}
document.addEventListener("keydown", (event) => {
  if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") { event.preventDefault(); openCommandPalette(); }
  if (event.key === "Escape") document.querySelector(".command-dialog")?.remove();
});
let detailPoll = null;
function scheduleDetailRefresh() {
  if (detailPoll) { clearTimeout(detailPoll); detailPoll = null; }
  if (document.querySelector("#rights-workspace:focus-within, #rights-workspace details[open]")) {
    detailPoll = setTimeout(scheduleDetailRefresh, 5000); return;
  }
  const active = new Set(["PREPARING", "QUEUED"]);
  if (state.view === "processing") {
    detailPoll = setTimeout(async () => {
      if (state.view !== "processing") return;
      if (document.hidden || document.querySelector("#followed-preparation:focus-within")) return scheduleDetailRefresh();
      try { await load("processing"); if (state.view === "processing") render(); } catch { scheduleDetailRefresh(); }
    }, state.processing?.followedPreparation?.refreshInProgress ? 5000 : 20000);
  } else if (state.view === "episodeDetail" && active.has(state.episodeDetail?.episode?.state)) {
    const { feedUrl } = state.episodeDetail.podcast, { id } = state.episodeDetail.episode;
    detailPoll = setTimeout(async () => { if (document.querySelector("#rights-workspace:focus-within, #rights-workspace details[open]")) return scheduleDetailRefresh(); if (state.view === "episodeDetail" && state.episodeDetail?.episode?.id === id) { try { await openEpisode(feedUrl, id); } catch {} } }, 5000);
  } else if (state.view === "podcastDetail" && state.podcastDetail?.episodes?.some((episode) => active.has(episode.state))) {
    const { feedUrl } = state.podcastDetail;
    detailPoll = setTimeout(async () => { if (document.querySelector("#rights-workspace:focus-within, #rights-workspace details[open]")) return scheduleDetailRefresh(); if (state.view === "podcastDetail" && state.podcastDetail?.feedUrl === feedUrl) { try { await openPodcast(feedUrl); } catch {} } }, 5000);
  }
}
function render() { ({ overview, podcasts, podcastDetail, episodeDetail, episodes, processing, listeners, operations, features, rights, policies, blocked, adSkip, intelligence, testing, translate, costs, audit, settings }[state.view] || overview)(); scheduleDetailRefresh(); }
